'use client';
import { useEffect, useState } from 'react';
import { useRouter }           from 'next/navigation';
import axios                   from 'axios';
import styles                  from '../dashboard.module.css';
import Card                    from '@/components/ui/Card/Card';
import StatCard                from '@/components/ui/StatCard/StatCard';
import Badge                   from '@/components/ui/Badge/Badge';
import Button                  from '@/components/ui/Button/Button';
import Spinner                 from '@/components/ui/Spinner/Spinner';
import { useAuthStore }        from '@/store/authStore';
import { formatNaira }         from '@/utils/formatCurrency';
import { formatDate }          from '@/utils/formatDate';

export default function ProcurementDashboard() {
  const { token }              = useAuthStore();
    const router                 = useRouter();
      const [reqs,    setReqs]     = useState([]);
        const [queue,   setQueue]    = useState([]);
          const [vendors, setVendors]  = useState([]);
            const [lpos,    setLpos]     = useState([]);
              const [loading, setLoading]  = useState(true);

                useEffect(() => {
                    const h = { Authorization: `Bearer ${token}` };
                        Promise.all([
                              axios.get('/api/requisitions', { headers: h }),
                                    axios.get('/api/approvals',    { headers: h }),
                                          axios.get('/api/vendors',      { headers: h }),
                                                axios.get('/api/lpo',          { headers: h }),
                                                    ]).then(([r1, r2, r3, r4]) => {
                                                          setReqs(r1.data.data    || []);
                                                                setQueue(r2.data.data   || []);
                                                                      setVendors(r3.data.data || []);
                                                                            setLpos(r4.data.data    || []);
                                                                                }).finally(() => setLoading(false));
                                                                                  }, [token]);

                                                                                    const totalReqs    = reqs.length;
                                                                                      const totalLPOs    = lpos.length;
                                                                                        const totalVendors = vendors.length;
                                                                                          const totalValue   = reqs.filter((r) => r.status === 'approved')
                                                                                              .reduce((s, r) => s + (r.totalAmount || 0), 0);

                                                                                                if (loading) return (
                                                                                                    <div style={{ display: 'flex', justifyContent: 'center', padding: 60 }}>
                                                                                                          <Spinner />
                                                                                                              </div>
                                                                                                                );

                                                                                                                  return (
                                                                                                                      <div className={styles.page}>
                                                                                                                            <div className={styles.welcome}>
                                                                                                                                    <div className={styles.welcomeText}>
                                                                                                                                              <h2>Procurement Dashboard 🏢</h2>
                                                                                                                                                        <p>Manage procurement activities, vendors and purchase orders.</p>
                                                                                                                                                                </div>
                                                                                                                                                                        {queue.length > 0 && (
                                                                                                                                                                                  <Button onClick={() => router.push('/approvals')} variant="gold" icon="bi-bell">
                                                                                                                                                                                              {queue.length} Pending Review
                                                                                                                                                                                                        </Button>
                                                                                                                                                                                                                )}
                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                            <div className={styles.statsGrid}>
                                                                                                                                                                                                                                    <StatCard label="All Requisitions"  value={totalReqs}            icon="bi-clipboard-text"  />
                                                                                                                                                                                                                                            <StatCard label="Pending My Review" value={queue.length}         icon="bi-hourglass"        accent="var(--gold)"   />
                                                                                                                                                                                                                                                    <StatCard label="LPOs Issued"       value={totalLPOs}            icon="bi-file-text"        accent="var(--blue)"   />
                                                                                                                                                                                                                                                            <StatCard label="Approved Value"    value={formatNaira(totalValue)} icon="bi-cash-stack"    accent="var(--accent)" />
                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                        <div className={styles.grid2}>
                                                                                                                                                                                                                                                                                {/* Approval queue */}
                                                                                                                                                                                                                                                                                        <Card>
                                                                                                                                                                                                                                                                                                  <div className={styles.sectionHeader}>
                                                                                                                                                                                                                                                                                                              <div className={styles.sectionTitle}>My Approval Queue</div>
                                                                                                                                                                                                                                                                                                                          <button className={styles.viewAll} onClick={() => router.push('/approvals')}>
                                                                                                                                                                                                                                                                                                                                        View all →
                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                        {queue.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                    <div style={{ textAlign: 'center', padding: '32px 0', color: 'var(--muted)' }}>
                                                                                                                                                                                                                                                                                                                                                                                                  <i className="bi bi-check-all" style={{ fontSize: 36, color: 'var(--accent)' }} />
                                                                                                                                                                                                                                                                                                                                                                                                                <div style={{ marginTop: 8 }}>No pending reviews</div>
                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                      ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                  queue.slice(0, 4).map((r) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                key={r._id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                className={styles.approvalCard}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onClick={() => router.push(`/requisitions/${r._id}`)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className={styles.approvalId}>{r.reqNumber}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className={styles.approvalTitle}>{r.title}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className={styles.approvalMeta}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {r.department?.name} •
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <strong style={{ color: 'var(--accent)', marginLeft: 4 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {formatNaira(r.totalAmount)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </strong>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </Card>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* Recent LPOs */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className={styles.sectionHeader}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className={styles.sectionTitle}>Recent LPOs</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button className={styles.viewAll} onClick={() => router.push('/lpo')}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    View all →
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {lpos.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div style={{ textAlign: 'center', padding: '32px 0', color: 'var(--muted)' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <i className="bi bi-file-earmark-x" style={{ fontSize: 32 }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div style={{ marginTop: 8 }}>No LPOs yet</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              lpos.slice(0, 4).map((l) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            key={l._id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            className={styles.reqItem}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onClick={() => router.push(`/lpo/${l._id}`)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style={{ cursor: 'pointer' }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className={styles.reqInfo}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className={styles.reqTitle}>{l.lpoNumber}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className={styles.reqMeta}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {l.vendor?.name} • {formatDate(l.createdAt)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className={styles.reqRight}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Badge status={l.status} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {/* Quick actions */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className={styles.grid4}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      { label: 'Review Approvals', icon: 'bi-check-circle',    href: '/approvals',     color: 'var(--gold)'   },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                { label: 'Manage Vendors',   icon: 'bi-building',        href: '/vendors',        color: 'var(--blue)'   },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          { label: 'Generate LPO',     icon: 'bi-file-earmark-plus',href: '/lpo',           color: 'var(--accent)' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    { label: 'View Reports',     icon: 'bi-bar-chart-line',  href: '/reports',        color: 'var(--purple)' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ].map((a) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  key={a.label}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className={styles.quickAction}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onClick={() => router.push(a.href)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <i className={`bi ${a.icon}`} style={{ fontSize: 22, color: a.color, display: 'block', marginBottom: 8 }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className={styles.qaLabel}>{a.label}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }